from shop.errors import NotFound, ValidationError


class App:
    def __init__(self, cart_service):
        self.carts = cart_service
        self._routes = {
            "create_cart": self._create_cart,
            "add_item": self._add_item,
            "remove_item": self._remove_item,
            "cart_summary": self._cart_summary,
        }

    def handle(self, request: dict) -> dict:
        action = request.get("action")
        handler = self._routes.get(action)
        if handler is None:
            return {"status": 404, "error": f"Unknown action: {action}"}
        try:
            result = handler(request.get("params", {}))
            return {"status": 200, "result": result}
        except NotFound as e:
            return {"status": 404, "error": str(e)}
        except ValidationError as e:
            return {"status": 400, "error": str(e)}
        except ValueError as e:
            return {"status": 400, "error": str(e)}

    def _create_cart(self, params):
        cart = self.carts.create_cart()
        return {"cart_id": cart.cart_id}

    def _add_item(self, params):
        cart_id = params["cart_id"]
        product_id = params["product_id"]
        quantity = params["quantity"]
        self.carts.add_item(cart_id, product_id, quantity)
        return self.carts.summary(cart_id)

    def _remove_item(self, params):
        cart_id = params["cart_id"]
        product_id = params["product_id"]
        self.carts.remove_item(cart_id, product_id)
        return self.carts.summary(cart_id)

    def _cart_summary(self, params):
        return self.carts.summary(params["cart_id"])
