from shop.errors import ValidationError


class Coupon:
    def __init__(self, code, kind, value):
        if not code:
            raise ValidationError("Coupon code must be a non-empty string.")
        if kind not in ("percent", "fixed"):
            raise ValidationError("Coupon kind must be 'percent' or 'fixed'.")
        if kind == "percent":
            if not isinstance(value, int) or isinstance(value, bool):
                raise ValidationError("Percent value must be an integer.")
            if value < 0 or value > 100:
                raise ValidationError("Percent value must be between 0 and 100 inclusive.")
        if kind == "fixed":
            if not isinstance(value, int) or isinstance(value, bool):
                raise ValidationError("Fixed value must be a non-negative integer number of cents.")
            if value < 0:
                raise ValidationError("Fixed value must be non-negative.")
        self.code = code
        self.kind = kind
        self.value = value

    def discount_for(self, subtotal_cents):
        if self.kind == "percent":
            discount = round(subtotal_cents * self.value / 100)
        else:
            discount = min(self.value, subtotal_cents)
        # Clamp to [0, subtotal_cents]
        discount = max(0, min(discount, subtotal_cents))
        return discount
