"""Generic in-memory collection used by all stores."""
from shop.errors import NotFound


class InMemoryCollection:
    def __init__(self):
        self._store = {}

    def put(self, key, value):
        self._store[key] = value
        return value

    def get(self, key):
        try:
            return self._store[key]
        except KeyError:
            raise NotFound(f"No item with key {key!r}")

    def has(self, key):
        return key in self._store

    def delete(self, key):
        if key not in self._store:
            raise NotFound(f"No item with key {key!r}")
        del self._store[key]

    def all(self):
        return list(self._store.values())
