"""Cart aggregate."""
from shop.errors import NotFound


class Cart:
    def __init__(self, cart_id: str, owner: str = ""):
        self.cart_id = cart_id
        self.owner   = owner
        self.items   = {}   # sku -> {"qty": int, "unit_price_cents": int}
        self.coupon  = None

    def add_item(self, sku: str, qty: int, unit_price_cents: int):
        if qty <= 0:
            raise ValueError("qty must be positive")
        if sku in self.items:
            self.items[sku]["qty"] += qty
        else:
            self.items[sku] = {"qty": qty, "unit_price_cents": unit_price_cents}

    def remove_item(self, sku: str):
        if sku not in self.items:
            raise NotFound(f"sku {sku!r} not in cart")
        del self.items[sku]

    def apply_coupon(self, coupon):
        self.coupon = coupon

    def subtotal_cents(self) -> int:
        return sum(v["qty"] * v["unit_price_cents"] for v in self.items.values())

    def discount_cents(self) -> int:
        if self.coupon is None:
            return 0
        return self.coupon.discount_for(self.subtotal_cents())

    def total_cents(self) -> int:
        return self.subtotal_cents() - self.discount_cents()
